window.CODE_INDEX = {"classes":{"AccountData":{"appearsIn":[["rally","h-classes","Logic \u00b7 class diagram"]],"code":"/// A data model for an account.\n///\n/// The [primaryAmount] is the balance of the account in USD.\nclass AccountData {\n  const AccountData({\n    required this.name,\n    required this.primaryAmount,\n    required this.accountNumber,\n  });\n\n  /// The display name of this entity.\n  final String name;\n\n  /// The primary amount or value of this entity.\n  final double primaryAmount;\n\n  /// The full displayable account number.\n  final String accountNumber;\n}","file":"lib/studies/rally/data.dart","kind":"class","line":41,"members":{"AccountData":[45,49],"accountNumber":[57,58],"name":[51,52],"primaryAmount":[54,55]},"supers":[]},"AccountsView":{"appearsIn":[["rally","h-widgets","Screen \u00b7 widget composition"],["rally","h-sequence","Sign in and open an account \u00b7 sequence"]],"code":"/// A page that shows a summary of accounts.\nclass AccountsView extends StatelessWidget {\n  const AccountsView({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    final items = DummyDataService.getAccountDataList(context);\n    final detailItems = DummyDataService.getAccountDetailList(context);\n    final balanceTotal = sumAccountDataPrimaryAmount(items);\n\n    return TabWithSidebar(\n      restorationId: 'accounts_view',\n      mainView: FinancialEntityView(\n        heroLabel: GalleryLocalizations.of(context)!.rallyAccountTotal,\n        heroAmount: balanceTotal,\n        segments: buildSegmentsFromAccountItems(items),\n        wholeAmount: balanceTotal,\n        financialEntityCards: buildAccountDataListViews(items, context),\n      ),\n      sidebarItems: [\n        for (UserDetailData item in detailItems)\n          SidebarItem(title: item.title, value: item.value)\n      ],\n    );\n  }\n}","file":"lib/studies/rally/tabs/accounts.dart","kind":"class","line":13,"members":{"AccountsView":[15,15],"build":[17,37]},"shot":"shots/code/AccountsView.jpg","supers":["StatelessWidget"]},"AlertData":{"appearsIn":[["rally","h-classes","Logic \u00b7 class diagram"]],"code":"/// A data model for an alert.\nclass AlertData {\n  AlertData({this.message, this.iconData});\n\n  /// The alert message to display.\n  final String? message;\n\n  /// The icon to display with the alert.\n  final IconData? iconData;\n}","file":"lib/studies/rally/data.dart","kind":"class","line":105,"members":{"AlertData":[107,107],"iconData":[112,113],"message":[109,110]},"supers":[]},"BillData":{"appearsIn":[["rally","h-classes","Logic \u00b7 class diagram"]],"code":"/// A data model for a bill.\n///\n/// The [primaryAmount] is the amount due in USD.\nclass BillData {\n  const BillData({\n    required this.name,\n    required this.primaryAmount,\n    required this.dueDate,\n    this.isPaid = false,\n  });\n\n  /// The display name of this entity.\n  final String name;\n\n  /// The primary amount or value of this entity.\n  final double primaryAmount;\n\n  /// The due date of this bill.\n  final String dueDate;\n\n  /// If this bill has been paid.\n  final bool isPaid;\n}","file":"lib/studies/rally/data.dart","kind":"class","line":61,"members":{"BillData":[65,70],"dueDate":[78,79],"isPaid":[81,82],"name":[72,73],"primaryAmount":[75,76]},"supers":[]},"BillsView":{"appearsIn":[["rally","h-widgets","Screen \u00b7 widget composition"]],"code":"/// A page that shows a summary of bills.\nclass BillsView extends StatefulWidget {\n  const BillsView({super.key});\n\n  @override\n  State<BillsView> createState() => _BillsViewState();\n}","file":"lib/studies/rally/tabs/bills.dart","kind":"class","line":13,"members":{"BillsView":[15,15],"createState":[17,18]},"shot":"shots/code/BillsView.jpg","supers":["StatefulWidget","_BillsViewState"]},"BudgetData":{"appearsIn":[["rally","h-classes","Logic \u00b7 class diagram"]],"code":"/// A data model for a budget.\n///\n/// The [primaryAmount] is the budget cap in USD.\nclass BudgetData {\n  const BudgetData({\n    required this.name,\n    required this.primaryAmount,\n    required this.amountUsed,\n  });\n\n  /// The display name of this entity.\n  final String name;\n\n  /// The primary amount or value of this entity.\n  final double primaryAmount;\n\n  /// Amount of the budget that is consumed or used.\n  final double amountUsed;\n}","file":"lib/studies/rally/data.dart","kind":"class","line":85,"members":{"BudgetData":[89,93],"amountUsed":[101,102],"name":[95,96],"primaryAmount":[98,99]},"supers":[]},"BudgetsView":{"appearsIn":[["rally","h-widgets","Screen \u00b7 widget composition"]],"code":"class BudgetsView extends StatefulWidget {\n  const BudgetsView({super.key});\n\n  @override\n  State<BudgetsView> createState() => _BudgetsViewState();\n}","file":"lib/studies/rally/tabs/budgets.dart","kind":"class","line":13,"members":{"BudgetsView":[14,14],"createState":[16,17]},"shot":"shots/code/BudgetsView.jpg","supers":["StatefulWidget","_BudgetsViewState"]},"DetailedEventData":{"appearsIn":[["rally","h-classes","Logic \u00b7 class diagram"]],"code":"class DetailedEventData {\n  const DetailedEventData({\n    required this.title,\n    required this.date,\n    required this.amount,\n  });\n\n  final String title;\n  final DateTime date;\n  final double amount;\n}","file":"lib/studies/rally/data.dart","kind":"class","line":116,"members":{"DetailedEventData":[117,121],"amount":[125,125],"date":[124,124],"title":[123,123]},"supers":[]},"DummyDataService":{"appearsIn":[["rally","h-classes","Logic \u00b7 class diagram"],["rally","h-sequence","Sign in and open an account \u00b7 sequence"]],"code":"/// Class to return dummy data lists.\n///\n/// In a real app, this might be replaced with some asynchronous service.\nclass DummyDataService {\n  static List<AccountData> getAccountDataList(BuildContext context) {\n    final localizations = GalleryLocalizations.of(context)!;\n    return <AccountData>[\n      AccountData(\n        name: localizations.rallyAccountDataChecking,\n        primaryAmount: 2215.13,\n        accountNumber: '1234561234',\n      ),\n      AccountData(\n        name: localizations.rallyAccountDataHomeSavings,\n        primaryAmount: 8678.88,\n        accountNumber: '8888885678',\n      ),\n      AccountData(\n        name: localizations.rallyAccountDataCarSavings,\n        primaryAmount: 987.48,\n        accountNumber: '8888889012',\n      ),\n      AccountData(\n        name: localizations.rallyAccountDataVacation,\n        primaryAmount: 253,\n        accountNumber: '1231233456',\n      ),\n    ];\n  }\n\n  static List<UserDetailData> getAccountDetailList(BuildContext context) {\n    final localizations = GalleryLocalizations.of(context)!;\n    return <UserDetailData>[\n      UserDetailData(\n        title: localizations.rallyAccountDetailDataAnnualPercentageYield,\n        value: percentFormat(context).format(0.001),\n      ),\n      UserDetailData(\n        title: localizations.rallyAccountDetailDataInterestRate,\n        value: usdWithSignFormat(context).format(1676.14),\n      ),\n      UserDetailData(\n        title: localizations.rallyAccountDetailDataInterestYtd,\n        value: usdWithSignFormat(context).format(81.45),\n      ),\n      UserDetailData(\n        title: localizations.rallyAccountDetailDataInterestPaidLastYear,\n        value: usdWithSignFormat(context).format(987.12),\n      ),\n      UserDetailData(\n        title: localizations.rallyAccountDetailDataNextStatement,\n        value: shortDateFormat(context).format(DateTime.utc(2019, 12, 25)),\n      ),\n      UserDetailData(\n        title: localizations.rallyAccountDetailDataAccountOwner,\n        value: 'Philip Cao',\n      ),\n    ];\n  }\n\n  static List<DetailedEventData> getDetailedEventItems() {\n    // The following titles are not localized as they're product/brand names.\n    return <DetailedEventData>[\n      DetailedEventData(\n        title: 'Genoe',\n        date: DateTime.utc(2019, 1, 24),\n        amount: -16.54,\n      ),\n      DetailedEventData(\n        title: 'Fortnightly Subscribe',\n        date: DateTime.utc(2019, 1, 5),\n        amount: -12.54,\n      ),\n      DetailedEventData(\n        title: 'Circle Cash',\n        date: DateTime.utc(2019, 1, 5),\n        amount: 365.65,\n      ),\n      DetailedEventData(\n        title: 'Crane Hospitality',\n        date: DateTime.utc(2019, 1, 4),\n        amount: -705.13,\n      ),\n      DetailedEventData(\n        title: 'ABC Payroll',\n        date: DateTime.utc(2018, 12, 15),\n        amount: 1141.43,\n      ),\n      DetailedEventData(\n        title: 'Shrine',\n        date: DateTime.utc(2018, 12, 15),\n        amount: -88.88,\n      ),\n      DetailedEventData(\n        title: 'Foodmates',\n        date: DateTime.utc(2018, 12, 4),\n        amount: -11.69,\n      ),\n    ];\n  }\n\n  static List<BillData> getBillDataList(BuildContext context) {\n    // The following names are not localized as they're product/brand names.\n    return <BillData>[\n      BillData(\n        name: 'RedPay Credit',\n        primaryAmount: 45.36,\n        dueDate: dateFormatAbbreviatedMonthDay(context)\n            .format(DateTime.utc(2019, 1, 29)),\n      ),\n      BillData(\n        name: 'Rent',\n        primaryAmount: 1200,\n        dueDate: dateFormatAbbreviatedMonthDay(context)\n            .format(DateTime.utc(2019, 2, 9)),\n        isPaid: true,\n      ),\n      BillData(\n        name: 'TabFine Credit',\n        primaryAmount: 87.33,\n        dueDate: dateFormatAbbreviatedMonthDay(context)\n            .format(DateTime.utc(2019, 2, 22)),\n      ),\n      BillData(\n        name: 'ABC Loans',\n        primaryAmount: 400,\n        dueDate: dateFormatAbbreviatedMonthDay(context)\n            .format(DateTime.utc(2019, 2, 29)),\n      ),\n    ];\n  }\n\n  static List<UserDetailData> getBillDetailList(BuildContext context,\n      {required double dueTotal, required double paidTotal}) {\n    final localizations = GalleryLocalizations.of(context)!;\n    return <UserDetailData>[\n      UserDetailData(\n        title: localizations.rallyBillDetailTotalAmount,\n        value: usdWithSignFormat(context).format(paidTotal + dueTotal),\n      ),\n      UserDetailData(\n        title: localizations.rallyBillDetailAmountPaid,\n        value: usdWithSignFormat(context).format(paidTotal),\n      ),\n      UserDetailData(\n        title: localizations.rallyBillDetailAmountDue,\n        value: usdWithSignFormat(context).format(dueTotal),\n      ),\n    ];\n  }\n\n  static List<BudgetData> getBudgetDataList(BuildContext context) {\n    final localizations = GalleryLocalizations.of(context)!;\n    return <BudgetData>[\n      BudgetData(\n        name: localizations.rallyBudgetCategoryCoffeeShops,\n        primaryAmount: 70,\n        amountUsed: 45.49,\n      ),\n      BudgetData(\n        name: localizations.rallyBudgetCategoryGroceries,\n        primaryAmount: 170,\n        amountUsed: 16.45,\n      ),\n      BudgetData(\n        name: localizations.rallyBudgetCategoryRestaurants,\n        primaryAmount: 170,\n        amountUsed: 123.25,\n      ),\n      BudgetData(\n        name: localizations.rallyBudgetCategoryClothing,\n        primaryAmount: 70,\n        amountUsed: 19.45,\n      ),\n    ];\n  }\n\n  static List<UserDetailData> getBudgetDetailList(BuildContext context,\n      {required double capTotal, required double usedTotal}) {\n    final localizations = GalleryLocalizations.of(context)!;\n    return <UserDetailData>[\n      UserDetailData(\n        title: localizations.rallyBudgetDetailTotalCap,\n        value: usdWithSignFormat(context).format(capTotal),\n      ),\n      UserDetailData(\n        title: localizations.rallyBudgetDetailAmountUsed,\n        value: usdWithSignFormat(context).format(usedTotal),\n      ),\n      UserDetailData(\n        title: localizations.rallyBudgetDetailAmountLeft,\n        value: usdWithSignFormat(context).format(capTotal - usedTotal),\n      ),\n    ];\n  }\n\n  static List<String> getSettingsTitles(BuildContext context) {\n    final localizations = GalleryLocalizations.of(context)!;\n    return <String>[\n      localizations.rallySettingsManageAccounts,\n      localizations.rallySettingsTaxDocuments,\n      localizations.rallySettingsPasscodeAndTouchId,\n      localizations.rallySettingsNotifications,\n      localizations.rallySettingsPersonalInformation,\n      localizations.rallySettingsPaperlessSettings,\n      localizations.rallySettingsFindAtms,\n      localizations.rallySettingsHelp,\n      localizations.rallySettingsSignOut,\n    ];\n  }\n\n  static List<AlertData> getAlerts(BuildContext context) {\n    final localizations = GalleryLocalizations.of(context)!;\n    return <AlertData>[\n      AlertData(\n        message: localizations.rallyAlertsMessageHeadsUpShopping(\n            percentFormat(context, decimalDigits: 0).format(0.9)),\n        iconData: Icons.sort,\n      ),\n      AlertData(\n        message: localizations.rallyAlertsMessageSpentOnRestaurants(\n            usdWithSignFormat(context, decimalDigits: 0).format(120)),\n        iconData: Icons.sort,\n      ),\n      AlertData(\n        message: localizations.rallyAlertsMessageATMFees(\n            usdWithSignFormat(context, decimalDigits: 0).format(24)),\n        iconData: Icons.credit_card,\n      ),\n      AlertData(\n        message: localizations.rallyAlertsMessageCheckingAccount(\n            percentFormat(context, decimalDigits: 0).format(0.04)),\n        iconData: Icons.attach_money,\n      ),\n      AlertData(\n        message: localizations.rallyAlertsMessageUnassignedTransactions(16),\n        iconData: Icons.not_interested,\n      ),\n    ];\n  }\n}","file":"lib/studies/rally/data.dart","kind":"class","line":142,"members":{"getAccountDataList":[146,170],"getAccountDetailList":[172,200],"getAlerts":[353,381],"getBillDataList":[243,272],"getBillDetailList":[274,291],"getBudgetDataList":[293,317],"getBudgetDetailList":[319,336],"getDetailedEventItems":[202,241],"getSettingsTitles":[338,351]},"supers":[]},"FinancialEntityCategoryDetailsPage":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["rally","h-widgets","Screen \u00b7 widget composition"],["rally","h-sequence","Sign in and open an account \u00b7 sequence"]],"code":"class FinancialEntityCategoryDetailsPage extends StatelessWidget {\n  FinancialEntityCategoryDetailsPage({super.key});\n\n  final List<DetailedEventData> items =\n      DummyDataService.getDetailedEventItems();\n\n  @override\n  Widget build(BuildContext context) {\n    final isDesktop = isDisplayDesktop(context);\n\n    return ApplyTextOptions(\n      child: Scaffold(\n        appBar: AppBar(\n          elevation: 0,\n          centerTitle: true,\n          title: Text(\n            GalleryLocalizations.of(context)!.rallyAccountDataChecking,\n            style:\n                Theme.of(context).textTheme.bodyMedium!.copyWith(fontSize: 18),\n          ),\n        ),\n        body: Column(\n          children: [\n            SizedBox(\n              height: 200,\n              width: double.infinity,\n              child: RallyLineChart(events: items),\n            ),\n            Expanded(\n              child: Padding(\n                padding: isDesktop ? const EdgeInsets.all(40) : EdgeInsets.zero,\n                child: ListView(\n                  shrinkWrap: true,\n                  children: [\n                    for (DetailedEventData detailedEventData in items)\n                      _DetailedEventCard(\n                        title: detailedEventData.title,\n                        date: detailedEventData.date,\n                        amount: detailedEventData.amount,\n                      ),\n                  ],\n                ),\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}","file":"lib/studies/rally/finance.dart","kind":"class","line":318,"members":{"FinancialEntityCategoryDetailsPage":[319,319],"build":[324,366],"items":[321,322]},"shot":"shots/code/FinancialEntityCategoryDetailsPage.jpg","supers":["StatelessWidget"]},"FinancialEntityCategoryView":{"appearsIn":[["rally","h-widgets","Screen \u00b7 widget composition"],["rally","h-sequence","Sign in and open an account \u00b7 sequence"]],"code":"/// A reusable widget to show balance information of a single entity as a card.\nclass FinancialEntityCategoryView extends StatelessWidget {\n  const FinancialEntityCategoryView({\n    super.key,\n    required this.indicatorColor,\n    required this.indicatorFraction,\n    required this.title,\n    required this.subtitle,\n    required this.semanticsLabel,\n    required this.amount,\n    required this.suffix,\n  });\n\n  final Color indicatorColor;\n  final double indicatorFraction;\n  final String title;\n  final String subtitle;\n  final String semanticsLabel;\n  final String amount;\n  final Widget suffix;\n\n  @override\n  Widget build(BuildContext context) {\n    final textTheme = Theme.of(context).textTheme;\n    return Semantics.fromProperties(\n      properties: SemanticsProperties(\n        button: true,\n        enabled: true,\n        label: semanticsLabel,\n      ),\n      excludeSemantics: true,\n      // TODO(x): State restoration of FinancialEntityCategoryDetailsPage on mobile is blocked because OpenContainer does not support restorablePush, https://github.com/flutter/gallery/issues/570.\n      child: OpenContainer(\n        transitionDuration: const Duration(milliseconds: 350),\n        transitionType: ContainerTransitionType.fade,\n        openBuilder: (context, openContainer) =>\n            FinancialEntityCategoryDetailsPage(),\n        openColor: RallyColors.primaryBackground,\n        closedColor: RallyColors.primaryBackground,\n        closedElevation: 0,\n        closedBuilder: (context, openContainer) {\n          return TextButton(\n            style: TextButton.styleFrom(foregroundColor: Colors.black),\n            onPressed: openContainer,\n            child: Column(\n              children: [\n                Container(\n                  padding:\n                      const EdgeInsets.symmetric(vertical: 16, horizontal: 8),\n                  child: Row(\n                    children: [\n                      Container(\n                        alignment: Alignment.center,\n                        height: 32 + 60 * (cappedTextScale(context) - 1),\n                        padding: const EdgeInsets.symmetric(horizontal: 12),\n                        child: VerticalFractionBar(\n                          color: indicatorColor,\n                          fraction: indicatorFraction,\n                        ),\n                      ),\n                      Expanded(\n                        child: Wrap(\n                          alignment: WrapAlignment.spaceBetween,\n                          crossAxisAlignment: WrapCrossAlignment.center,\n                          children: [\n                            Column(\n                              mainAxisAlignment: MainAxisAlignment.center,\n                              crossAxisAlignment: CrossAxisAlignment.start,\n                              children: [\n                                Text(\n                                  title,\n                                  style: textTheme.bodyMedium!\n                                      .copyWith(fontSize: 16),\n                                ),\n                                Text(\n                                  subtitle,\n                                  style: textTheme.bodyMedium!\n                                      .copyWith(color: RallyColors.gray60),\n                                ),\n                              ],\n                            ),\n                            Text(\n                              amount,\n                              style: textTheme.bodyLarge!.copyWith(\n                                fontSize: 20,\n                                color: RallyColors.gray,\n                              ),\n                            ),\n                          ],\n                        ),\n                      ),\n                      Container(\n                        constraints: const BoxConstraints(minWidth: 32),\n                        padding: const EdgeInsetsDirectional.only(start: 12),\n                        child: suffix,\n                      ),\n                    ],\n                  ),\n                ),\n                const Divider(\n                  height: 1,\n                  indent: 16,\n                  endIndent: 16,\n                  color: RallyColors.dividerColor,\n                ),\n              ],\n            ),\n          );\n        },\n      ),\n    );\n  }\n}","file":"lib/studies/rally/finance.dart","kind":"class","line":80,"members":{"FinancialEntityCategoryView":[82,91],"amount":[98,98],"build":[101,191],"indicatorColor":[93,93],"indicatorFraction":[94,94],"semanticsLabel":[97,97],"subtitle":[96,96],"suffix":[99,99],"title":[95,95]},"shot":"shots/code/FinancialEntityCategoryView.jpg","supers":["StatelessWidget"]},"FinancialEntityView":{"appearsIn":[["rally","h-widgets","Screen \u00b7 widget composition"]],"code":"class FinancialEntityView extends StatelessWidget {\n  const FinancialEntityView({\n    super.key,\n    required this.heroLabel,\n    required this.heroAmount,\n    required this.wholeAmount,\n    required this.segments,\n    required this.financialEntityCards,\n  }) : assert(segments.length == financialEntityCards.length);\n\n  /// The amounts to assign each item.\n  final List<RallyPieChartSegment> segments;\n  final String heroLabel;\n  final double heroAmount;\n  final double wholeAmount;\n  final List<FinancialEntityCategoryView> financialEntityCards;\n\n  @override\n  Widget build(BuildContext context) {\n    final maxWidth = pieChartMaxSize + (cappedTextScale(context) - 1.0) * 100.0;\n    return LayoutBuilder(builder: (context, constraints) {\n      return Column(\n        children: [\n          ConstrainedBox(\n            constraints: BoxConstraints(\n              // We decrease the max height to ensure the [RallyPieChart] does\n              // not take up the full height when it is smaller than\n              // [kPieChartMaxSize].\n              maxHeight: math.min(\n                constraints.biggest.shortestSide * 0.9,\n                maxWidth,\n              ),\n            ),\n            child: RallyPieChart(\n              heroLabel: heroLabel,\n              heroAmount: heroAmount,\n              wholeAmount: wholeAmount,\n              segments: segments,\n            ),\n          ),\n          const SizedBox(height: 24),\n          Container(\n            height: 1,\n            constraints: BoxConstraints(maxWidth: maxWidth),\n            color: RallyColors.inputBackground,\n          ),\n          Container(\n            constraints: BoxConstraints(maxWidth: maxWidth),\n            color: RallyColors.cardBackground,\n            child: Column(\n              children: financialEntityCards,\n            ),\n          ),\n        ],\n      );\n    });\n  }\n}","file":"lib/studies/rally/finance.dart","kind":"class","line":21,"members":{"FinancialEntityView":[22,29],"build":[38,77],"financialEntityCards":[36,36],"heroAmount":[34,34],"heroLabel":[33,33],"segments":[31,32],"wholeAmount":[35,35]},"shot":"shots/code/FinancialEntityView.jpg","supers":["StatelessWidget"]},"OverviewView":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["rally","h-widgets","Screen \u00b7 widget composition"]],"code":"/// A page that shows a status overview.\nclass OverviewView extends StatefulWidget {\n  const OverviewView({super.key});\n\n  @override\n  State<OverviewView> createState() => _OverviewViewState();\n}","file":"lib/studies/rally/tabs/overview.dart","kind":"class","line":18,"members":{"OverviewView":[20,20],"createState":[22,23]},"shot":"shots/code/OverviewView.jpg","supers":["StatefulWidget","_OverviewViewState"]},"RallyApp":{"appearsIn":[["rally","h-classes","Logic \u00b7 class diagram"]],"code":"/// The RallyApp is a MaterialApp with a theme and 2 routes.\n///\n/// The home route is the main page with tabs for sub pages.\n/// The login route is the initial route.\nclass RallyApp extends StatelessWidget {\n  const RallyApp({super.key});\n\n  static const String loginRoute = routes.loginRoute;\n  static const String homeRoute = routes.homeRoute;\n\n  final sharedZAxisTransitionBuilder = const SharedAxisPageTransitionsBuilder(\n    fillColor: RallyColors.primaryBackground,\n    transitionType: SharedAxisTransitionType.scaled,\n  );\n\n  @override\n  Widget build(BuildContext context) {\n    return MaterialApp(\n      restorationScopeId: 'rally_app',\n      title: 'Rally',\n      debugShowCheckedModeBanner: false,\n      theme: _buildRallyTheme().copyWith(\n        platform: GalleryOptions.of(context).platform,\n        pageTransitionsTheme: PageTransitionsTheme(\n          builders: {\n            for (var type in TargetPlatform.values)\n              type: sharedZAxisTransitionBuilder,\n          },\n        ),\n      ),\n      localizationsDelegates: GalleryLocalizations.localizationsDelegates,\n      supportedLocales: GalleryLocalizations.supportedLocales,\n      locale: GalleryOptions.of(context).locale,\n      initialRoute: loginRoute,\n      routes: <String, WidgetBuilder>{\n        homeRoute: (context) => const HomePage(),\n        loginRoute: (context) => const LoginPage(),\n      },\n    );\n  }\n\n  ThemeData _buildRallyTheme() {\n    final base = ThemeData.dark();\n    return ThemeData(\n      appBarTheme: const AppBarTheme(\n        systemOverlayStyle: SystemUiOverlayStyle.light,\n        backgroundColor: RallyColors.primaryBackground,\n        elevation: 0,\n      ),\n      scaffoldBackgroundColor: RallyColors.primaryBackground,\n      focusColor: RallyColors.focusColor,\n      textTheme: _buildRallyTextTheme(base.textTheme),\n      inputDecorationTheme: const InputDecorationTheme(\n        labelStyle: TextStyle(\n          color: RallyColors.gray,\n          fontWeight: FontWeight.w500,\n        ),\n        filled: true,\n        fillColor: RallyColors.inputBackground,\n        focusedBorder: InputBorder.none,\n      ),\n      visualDensity: VisualDensity.standard,\n      colorScheme: base.colorScheme.copyWith(\n        primary: RallyColors.primaryBackground,\n      ),\n    );\n  }\n\n  TextTheme _buildRallyTextTheme(TextTheme base) {\n    return base\n        .copyWith(\n          bodyMedium: GoogleFonts.robotoCondensed(\n            fontSize: 14,\n            fontWeight: FontWeight.w400,\n            letterSpacing: letterSpacingOrNone(0.5),\n          ),\n          bodyLarge: GoogleFonts.eczar(\n            fontSize: 40,\n            fontWeight: FontWeight.w400,\n            letterSpacing: letterSpacingOrNone(1.4),\n          ),\n          labelLarge: GoogleFonts.robotoCondensed(\n            fontWeight: FontWeight.w700,\n            letterSpacing: letterSpacingOrNone(2.8),\n          ),\n          headlineSmall: GoogleFonts.eczar(\n            fontSize: 40,\n            fontWeight: FontWeight.w600,\n            letterSpacing: letterSpacingOrNone(1.4),\n          ),\n        )\n        .apply(\n          displayColor: Colors.white,\n          bodyColor: Colors.white,\n        );\n  }\n}","file":"lib/studies/rally/app.dart","kind":"class","line":17,"members":{"RallyApp":[22,22],"_buildRallyTextTheme":[85,112],"_buildRallyTheme":[58,83],"build":[32,56],"homeRoute":[25,25],"loginRoute":[24,24],"sharedZAxisTransitionBuilder":[27,30]},"shot":"shots/code/RallyApp.jpg","supers":["StatelessWidget"]},"RallyLineChart":{"appearsIn":[["rally","h-widgets","Screen \u00b7 widget composition"]],"code":"class RallyLineChart extends StatelessWidget {\n  const RallyLineChart({\n    super.key,\n    this.events = const <DetailedEventData>[],\n  });\n\n  final List<DetailedEventData> events;\n\n  @override\n  Widget build(BuildContext context) {\n    return CustomPaint(\n      painter: RallyLineChartPainter(\n        dateFormat: dateFormatMonthYear(context),\n        numberFormat: usdWithSignFormat(context),\n        events: events,\n        labelStyle: Theme.of(context).textTheme.bodyMedium!,\n        textDirection: GalleryOptions.of(context).resolvedTextDirection(),\n        textScaleFactor: reducedTextScale(context),\n        padding: isDisplayDesktop(context)\n            ? const EdgeInsets.symmetric(vertical: 22)\n            : EdgeInsets.zero,\n      ),\n    );\n  }\n}","file":"lib/studies/rally/charts/line_chart.dart","kind":"class","line":16,"members":{"RallyLineChart":[17,20],"build":[24,39],"events":[22,22]},"shot":"shots/code/RallyLineChart.jpg","supers":["StatelessWidget"]},"RallyPieChart":{"appearsIn":[["rally","h-widgets","Screen \u00b7 widget composition"]],"code":"/// An animated circular pie chart to represent pieces of a whole, which can\n/// have empty space.\nclass RallyPieChart extends StatefulWidget {\n  const RallyPieChart({\n    super.key,\n    required this.heroLabel,\n    required this.heroAmount,\n    required this.wholeAmount,\n    required this.segments,\n  });\n\n  final String heroLabel;\n  final double heroAmount;\n  final double wholeAmount;\n  final List<RallyPieChartSegment> segments;\n\n  @override\n  State<RallyPieChart> createState() => _RallyPieChartState();\n}","file":"lib/studies/rally/charts/pie_chart.dart","kind":"class","line":68,"members":{"RallyPieChart":[71,77],"createState":[84,85],"heroAmount":[80,80],"heroLabel":[79,79],"segments":[82,82],"wholeAmount":[81,81]},"shot":"shots/code/RallyPieChart.jpg","supers":["StatefulWidget","_RallyPieChartState"]},"SettingsView":{"appearsIn":[["rally","h-widgets","Screen \u00b7 widget composition"]],"code":"class SettingsView extends StatefulWidget {\n  const SettingsView({super.key});\n\n  @override\n  State<SettingsView> createState() => _SettingsViewState();\n}","file":"lib/studies/rally/tabs/settings.dart","kind":"class","line":11,"members":{"SettingsView":[12,12],"createState":[14,15]},"shot":"shots/code/SettingsView.jpg","supers":["StatefulWidget","_SettingsViewState"]},"TabWithSidebar":{"appearsIn":[["rally","h-widgets","Screen \u00b7 widget composition"]],"code":"class TabWithSidebar extends StatelessWidget {\n  const TabWithSidebar({\n    super.key,\n    this.restorationId,\n    required this.mainView,\n    required this.sidebarItems,\n  });\n\n  final Widget mainView;\n  final List<Widget> sidebarItems;\n  final String? restorationId;\n\n  @override\n  Widget build(BuildContext context) {\n    if (isDisplayDesktop(context)) {\n      return Row(\n        children: [\n          Flexible(\n            flex: 2,\n            child: SingleChildScrollView(\n              child: Padding(\n                padding: const EdgeInsets.symmetric(vertical: 24),\n                child: mainView,\n              ),\n            ),\n          ),\n          Expanded(\n            flex: 1,\n            child: Container(\n              color: RallyColors.inputBackground,\n              padding: const EdgeInsetsDirectional.only(start: 24),\n              height: double.infinity,\n              alignment: AlignmentDirectional.centerStart,\n              child: ListView(\n                shrinkWrap: true,\n                children: sidebarItems,\n              ),\n            ),\n          ),\n        ],\n      );\n    } else {\n      return SingleChildScrollView(\n        restorationId: restorationId,\n        child: mainView,\n      );\n    }\n  }\n}","file":"lib/studies/rally/tabs/sidebar.dart","kind":"class","line":9,"members":{"TabWithSidebar":[10,15],"build":[21,56],"mainView":[17,17],"restorationId":[19,19],"sidebarItems":[18,18]},"shot":"shots/code/TabWithSidebar.jpg","supers":["StatelessWidget"]},"VerticalFractionBar":{"appearsIn":[["rally","h-widgets","Screen \u00b7 widget composition"]],"code":"class VerticalFractionBar extends StatelessWidget {\n  const VerticalFractionBar({\n    super.key,\n    this.color,\n    required this.fraction,\n  });\n\n  final Color? color;\n  final double fraction;\n\n  @override\n  Widget build(BuildContext context) {\n    return LayoutBuilder(builder: (context, constraints) {\n      return SizedBox(\n        height: constraints.maxHeight,\n        width: 4,\n        child: Column(\n          children: [\n            SizedBox(\n              height: (1 - fraction) * constraints.maxHeight,\n              child: Container(\n                color: Colors.black,\n              ),\n            ),\n            SizedBox(\n              height: fraction * constraints.maxHeight,\n              child: Container(color: color),\n            ),\n          ],\n        ),\n      );\n    });\n  }\n}","file":"lib/studies/rally/charts/vertical_fraction_bar.dart","kind":"class","line":7,"members":{"VerticalFractionBar":[8,12],"build":[17,39],"color":[14,14],"fraction":[15,15]},"supers":["StatelessWidget"]},"_AlertsView":{"appearsIn":[["rally","h-widgets","Screen \u00b7 widget composition"]],"code":"class _AlertsView extends StatelessWidget {\n  const _AlertsView({this.alerts});\n\n  final List<AlertData>? alerts;\n\n  @override\n  Widget build(BuildContext context) {\n    final isDesktop = isDisplayDesktop(context);\n    final localizations = GalleryLocalizations.of(context)!;\n\n    return Container(\n      padding: const EdgeInsetsDirectional.only(start: 16, top: 4, bottom: 4),\n      color: RallyColors.cardBackground,\n      child: Column(\n        children: [\n          Container(\n            width: double.infinity,\n            padding:\n                isDesktop ? const EdgeInsets.symmetric(vertical: 16) : null,\n            child: MergeSemantics(\n              child: Wrap(\n                alignment: WrapAlignment.spaceBetween,\n                crossAxisAlignment: WrapCrossAlignment.center,\n                children: [\n                  Text(localizations.rallyAlerts),\n                  if (!isDesktop)\n                    TextButton(\n                      style: TextButton.styleFrom(\n                        foregroundColor: Colors.white,\n                      ),\n                      onPressed: () {},\n                      child: Text(localizations.rallySeeAll),\n                    ),\n                ],\n              ),\n            ),\n          ),\n          for (AlertData alert in alerts!) ...[\n            Container(color: RallyColors.primaryBackground, height: 1),\n            _Alert(alert: alert),\n          ]\n        ],\n      ),\n    );\n  }\n}","file":"lib/studies/rally/tabs/overview.dart","kind":"class","line":147,"members":{"_AlertsView":[148,148],"alerts":[150,150],"build":[152,191]},"shot":"shots/code/_AlertsView.jpg","supers":["StatelessWidget"]},"_BillsViewState":{"code":"class _BillsViewState extends State<BillsView>\n    with SingleTickerProviderStateMixin {\n  @override\n  Widget build(BuildContext context) {\n    final items = DummyDataService.getBillDataList(context);\n    final dueTotal = sumBillDataPrimaryAmount(items);\n    final paidTotal = sumBillDataPaidAmount(items);\n    final detailItems = DummyDataService.getBillDetailList(\n      context,\n      dueTotal: dueTotal,\n      paidTotal: paidTotal,\n    );\n\n    return TabWithSidebar(\n      restorationId: 'bills_view',\n      mainView: FinancialEntityView(\n        heroLabel: GalleryLocalizations.of(context)!.rallyBillsDue,\n        heroAmount: dueTotal,\n        segments: buildSegmentsFromBillItems(items),\n        wholeAmount: dueTotal,\n        financialEntityCards: buildBillDataListViews(items, context),\n      ),\n      sidebarItems: [\n        for (UserDetailData item in detailItems)\n          SidebarItem(title: item.title, value: item.value)\n      ],\n    );\n  }\n}","file":"lib/studies/rally/tabs/bills.dart","kind":"class","line":21,"members":{"build":[23,48]},"supers":["State","SingleTickerProviderStateMixin"]},"_BudgetsViewState":{"code":"class _BudgetsViewState extends State<BudgetsView>\n    with SingleTickerProviderStateMixin {\n  @override\n  Widget build(BuildContext context) {\n    final items = DummyDataService.getBudgetDataList(context);\n    final capTotal = sumBudgetDataPrimaryAmount(items);\n    final usedTotal = sumBudgetDataAmountUsed(items);\n    final detailItems = DummyDataService.getBudgetDetailList(\n      context,\n      capTotal: capTotal,\n      usedTotal: usedTotal,\n    );\n\n    return TabWithSidebar(\n      restorationId: 'budgets_view',\n      mainView: FinancialEntityView(\n        heroLabel: GalleryLocalizations.of(context)!.rallyBudgetLeft,\n        heroAmount: capTotal - usedTotal,\n        segments: buildSegmentsFromBudgetItems(items),\n        wholeAmount: capTotal,\n        financialEntityCards: buildBudgetDataListViews(items, context),\n      ),\n      sidebarItems: [\n        for (UserDetailData item in detailItems)\n          SidebarItem(title: item.title, value: item.value)\n      ],\n    );\n  }\n}","file":"lib/studies/rally/tabs/budgets.dart","kind":"class","line":20,"members":{"build":[22,47]},"supers":["State","SingleTickerProviderStateMixin"]},"_FinancialView":{"appearsIn":[["rally","h-widgets","Screen \u00b7 widget composition"]],"code":"class _FinancialView extends StatelessWidget {\n  const _FinancialView({\n    this.title,\n    this.total,\n    this.financialItemViews,\n    this.buttonSemanticsLabel,\n    this.order,\n  });\n\n  final String? title;\n  final String? buttonSemanticsLabel;\n  final double? total;\n  final List<FinancialEntityCategoryView>? financialItemViews;\n  final double? order;\n\n  @override\n  Widget build(BuildContext context) {\n    final theme = Theme.of(context);\n    return FocusTraversalOrder(\n      order: NumericFocusOrder(order!),\n      child: Container(\n        color: RallyColors.cardBackground,\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.stretch,\n          children: [\n            MergeSemantics(\n              child: Column(\n                crossAxisAlignment: CrossAxisAlignment.stretch,\n                children: [\n                  Padding(\n                    padding: const EdgeInsets.only(\n                      top: 16,\n                      left: 16,\n                      right: 16,\n                    ),\n                    child: SelectableText(title!),\n                  ),\n                  Padding(\n                    padding: const EdgeInsets.only(left: 16, right: 16),\n                    child: SelectableText(\n                      usdWithSignFormat(context).format(total),\n                      style: theme.textTheme.bodyLarge!.copyWith(\n                        fontSize: 44 / reducedTextScale(context),\n                        fontWeight: FontWeight.w600,\n                      ),\n                    ),\n                  ),\n                ],\n              ),\n            ),\n            ...financialItemViews!\n                .sublist(0, math.min(financialItemViews!.length, 3)),\n            TextButton(\n              style: TextButton.styleFrom(foregroundColor: Colors.white),\n              onPressed: () {},\n              child: Text(\n                GalleryLocalizations.of(context)!.rallySeeAll,\n                semanticsLabel: buttonSemanticsLabel,\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}","file":"lib/studies/rally/tabs/overview.dart","kind":"class","line":229,"members":{"_FinancialView":[230,236],"build":[244,293],"buttonSemanticsLabel":[239,239],"financialItemViews":[241,241],"order":[242,242],"title":[238,238],"total":[240,240]},"shot":"shots/code/_FinancialView.jpg","supers":["StatelessWidget"]},"_HomePageState":{"appearsIn":[["rally","h-classes","Logic \u00b7 class diagram"],["rally","h-widgets","Screen \u00b7 widget composition"],["rally","h-sequence","Sign in and open an account \u00b7 sequence"]],"code":"class _HomePageState extends State<HomePage>\n    with SingleTickerProviderStateMixin, RestorationMixin {\n  late TabController _tabController;\n  RestorableInt tabIndex = RestorableInt(0);\n\n  @override\n  String get restorationId => 'home_page';\n\n  @override\n  void restoreState(RestorationBucket? oldBucket, bool initialRestore) {\n    registerForRestoration(tabIndex, 'tab_index');\n    _tabController.index = tabIndex.value;\n  }\n\n  @override\n  void initState() {\n    super.initState();\n    _tabController = TabController(length: tabCount, vsync: this)\n      ..addListener(() {\n        // Set state to make sure that the [_RallyTab] widgets get updated when changing tabs.\n        setState(() {\n          tabIndex.value = _tabController.index;\n        });\n      });\n  }\n\n  @override\n  void dispose() {\n    _tabController.dispose();\n    tabIndex.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final theme = Theme.of(context);\n    final isDesktop = isDisplayDesktop(context);\n    Widget tabBarView;\n    if (isDesktop) {\n      final isTextDirectionRtl =\n          GalleryOptions.of(context).resolvedTextDirection() ==\n              TextDirection.rtl;\n      final verticalRotation =\n          isTextDirectionRtl ? turnsToRotateLeft : turnsToRotateRight;\n      final revertVerticalRotation =\n          isTextDirectionRtl ? turnsToRotateRight : turnsToRotateLeft;\n      tabBarView = Row(\n        children: [\n          Container(\n            width: 150 + 50 * (cappedTextScale(context) - 1),\n            alignment: Alignment.topCenter,\n            padding: const EdgeInsets.symmetric(vertical: 32),\n            child: Column(\n              children: [\n                const SizedBox(height: 24),\n                ExcludeSemantics(\n                  child: SizedBox(\n                    height: 80,\n                    child: Image.asset(\n                      'logo.png',\n                      package: 'rally_assets',\n                    ),\n                  ),\n                ),\n                const SizedBox(height: 24),\n                // Rotate the tab bar, so the animation is vertical for desktops.\n                RotatedBox(\n                  quarterTurns: verticalRotation,\n                  child: _RallyTabBar(\n                    tabs: _buildTabs(\n                            context: context, theme: theme, isVertical: true)\n                        .map(\n                      (widget) {\n                        // Revert the rotation on the tabs.\n                        return RotatedBox(\n                          quarterTurns: revertVerticalRotation,\n                          child: widget,\n                        );\n                      },\n                    ).toList(),\n                    tabController: _tabController,\n                  ),\n                ),\n              ],\n            ),\n          ),\n          Expanded(\n            // Rotate the tab views so we can swipe up and down.\n            child: RotatedBox(\n              quarterTurns: verticalRotation,\n              child: TabBarView(\n                controller: _tabController,\n                children: _buildTabViews().map(\n                  (widget) {\n                    // Revert the rotation on the tab views.\n                    return RotatedBox(\n                      quarterTurns: revertVerticalRotation,\n                      child: widget,\n                    );\n                  },\n                ).toList(),\n              ),\n            ),\n          ),\n        ],\n      );\n    } else {\n      tabBarView = Column(\n        children: [\n          _RallyTabBar(\n            tabs: _buildTabs(context: context, theme: theme),\n            tabController: _tabController,\n          ),\n          Expanded(\n            child: TabBarView(\n              controller: _tabController,\n              children: _buildTabViews(),\n            ),\n          ),\n        ],\n      );\n    }\n    return ApplyTextOptions(\n      child: Scaffold(\n        body: SafeArea(\n          // For desktop layout we do not want to have SafeArea at the top and\n          // bottom to display 100% height content on the accounts view.\n          top: !isDesktop,\n          bottom: !isDesktop,\n          child: Theme(\n            // This theme effectively removes the default visual touch\n            // feedback for tapping a tab, which is replaced with a custom\n            // animation.\n            data: theme.copyWith(\n              splashColor: Colors.transparent,\n              highlightColor: Colors.transparent,\n            ),\n            child: FocusTraversalGroup(\n              policy: OrderedTraversalPolicy(),\n              child: tabBarView,\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n\n  List<Widget> _buildTabs(\n      {required BuildContext context,\n      required ThemeData theme,\n      bool isVertical = false}) {\n    final localizations = GalleryLocalizations.of(context)!;\n    return [\n      _RallyTab(\n        theme: theme,\n        iconData: Icons.pie_chart,\n        title: localizations.rallyTitleOverview,\n        tabIndex: 0,\n        tabController: _tabController,\n        isVertical: isVertical,\n      ),\n      _RallyTab(\n        theme: theme,\n        iconData: Icons.attach_money,\n        title: localizations.rallyTitleAccounts,\n        tabIndex: 1,\n        tabController: _tabController,\n        isVertical: isVertical,\n      ),\n      _RallyTab(\n        theme: theme,\n        iconData: Icons.money_off,\n        title: localizations.rallyTitleBills,\n        tabIndex: 2,\n        tabController: _tabController,\n        isVertical: isVertical,\n      ),\n      _RallyTab(\n        theme: theme,\n        iconData: Icons.table_chart,\n        title: localizations.rallyTitleBudgets,\n        tabIndex: 3,\n        tabController: _tabController,\n        isVertical: isVertical,\n      ),\n      _RallyTab(\n        theme: theme,\n        iconData: Icons.settings,\n        title: localizations.rallyTitleSettings,\n        tabIndex: 4,\n        tabController: _tabController,\n        isVertical: isVertical,\n      ),\n    ];\n  }\n\n  List<Widget> _buildTabViews() {\n    return const [\n      OverviewView(),\n      AccountsView(),\n      BillsView(),\n      BudgetsView(),\n      SettingsView(),\n    ];\n  }\n}","file":"lib/studies/rally/home.dart","kind":"class","line":27,"members":{"_buildTabViews":[223,231],"_buildTabs":[174,221],"_tabController":[29,29],"build":[60,172],"dispose":[53,58],"initState":[41,51],"restorationId":[32,33],"restoreState":[35,39],"tabIndex":[30,30]},"supers":["State","SingleTickerProviderStateMixin","RestorationMixin"]},"_MainView":{"appearsIn":[["rally","h-classes","Logic \u00b7 class diagram"],["rally","h-sequence","Sign in and open an account \u00b7 sequence"]],"code":"class _MainView extends StatelessWidget {\n  const _MainView({\n    this.usernameController,\n    this.passwordController,\n  });\n\n  final TextEditingController? usernameController;\n  final TextEditingController? passwordController;\n\n  void _login(BuildContext context) {\n    Navigator.of(context).restorablePushNamed(RallyApp.homeRoute);\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final isDesktop = isDisplayDesktop(context);\n    List<Widget> listViewChildren;\n\n    if (isDesktop) {\n      final desktopMaxWidth = 400.0 + 100.0 * (cappedTextScale(context) - 1);\n      listViewChildren = [\n        _UsernameInput(\n          maxWidth: desktopMaxWidth,\n          usernameController: usernameController,\n        ),\n        const SizedBox(height: 12),\n        _PasswordInput(\n          maxWidth: desktopMaxWidth,\n          passwordController: passwordController,\n        ),\n        _LoginButton(\n          maxWidth: desktopMaxWidth,\n          onTap: () {\n            _login(context);\n          },\n        ),\n      ];\n    } else {\n      listViewChildren = [\n        const _SmallLogo(),\n        _UsernameInput(\n          usernameController: usernameController,\n        ),\n        const SizedBox(height: 12),\n        _PasswordInput(\n          passwordController: passwordController,\n        ),\n        _ThumbButton(\n          onTap: () {\n            _login(context);\n          },\n        ),\n      ];\n    }\n\n    return Column(\n      children: [\n        if (isDesktop) const _TopBar(),\n        Expanded(\n          child: Align(\n            alignment: isDesktop ? Alignment.center : Alignment.topCenter,\n            child: ListView(\n              restorationId: 'login_list_view',\n              shrinkWrap: true,\n              padding: const EdgeInsets.symmetric(horizontal: 24),\n              children: listViewChildren,\n            ),\n          ),\n        ),\n      ],\n    );\n  }\n}","file":"lib/studies/rally/login.dart","kind":"class","line":59,"members":{"_MainView":[60,63],"_login":[68,70],"build":[72,130],"passwordController":[66,66],"usernameController":[65,65]},"shot":"shots/code/_MainView.jpg","supers":["StatelessWidget"]},"_OverviewViewState":{"code":"class _OverviewViewState extends State<OverviewView> {\n  @override\n  Widget build(BuildContext context) {\n    final alerts = DummyDataService.getAlerts(context);\n\n    if (isDisplayDesktop(context)) {\n      const sortKeyName = 'Overview';\n      return SingleChildScrollView(\n        restorationId: 'overview_scroll_view',\n        child: Padding(\n          padding: const EdgeInsets.symmetric(vertical: 24),\n          child: Row(\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              Flexible(\n                flex: 7,\n                child: Semantics(\n                  sortKey: const OrdinalSortKey(1, name: sortKeyName),\n                  child: const _OverviewGrid(spacing: 24),\n                ),\n              ),\n              const SizedBox(width: 24),\n              Flexible(\n                flex: 3,\n                child: SizedBox(\n                  width: 400,\n                  child: Semantics(\n                    sortKey: const OrdinalSortKey(2, name: sortKeyName),\n                    child: FocusTraversalGroup(\n                      child: _AlertsView(alerts: alerts),\n                    ),\n                  ),\n                ),\n              ),\n            ],\n          ),\n        ),\n      );\n    } else {\n      return SingleChildScrollView(\n        restorationId: 'overview_scroll_view',\n        child: Padding(\n          padding: const EdgeInsets.symmetric(vertical: 12),\n          child: Column(\n            children: [\n              _AlertsView(alerts: alerts.sublist(0, 1)),\n              const SizedBox(height: 12),\n              const _OverviewGrid(spacing: 12),\n            ],\n          ),\n        ),\n      );\n    }\n  }\n}","file":"lib/studies/rally/tabs/overview.dart","kind":"class","line":26,"members":{"build":[27,79]},"supers":["State"]},"_RallyPieChartState":{"code":"class _RallyPieChartState extends State<RallyPieChart>\n    with SingleTickerProviderStateMixin {\n  late AnimationController controller;\n  late Animation<double> animation;\n\n  @override\n  void initState() {\n    super.initState();\n    controller = AnimationController(\n      duration: const Duration(milliseconds: 600),\n      vsync: this,\n    );\n    animation = CurvedAnimation(\n        parent: TweenSequence<double>(<TweenSequenceItem<double>>[\n          TweenSequenceItem<double>(\n            tween: Tween<double>(begin: 0, end: 0),\n            weight: 1,\n          ),\n          TweenSequenceItem<double>(\n            tween: Tween<double>(begin: 0, end: 1),\n            weight: 1.5,\n          ),\n        ]).animate(controller),\n        curve: Curves.decelerate);\n    controller.forward();\n  }\n\n  @override\n  void dispose() {\n    controller.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return MergeSemantics(\n      child: _AnimatedRallyPieChart(\n        animation: animation,\n        centerLabel: widget.heroLabel,\n        centerAmount: widget.heroAmount,\n        total: widget.wholeAmount,\n        segments: widget.segments,\n      ),\n    );\n  }\n}","file":"lib/studies/rally/charts/pie_chart.dart","kind":"class","line":88,"members":{"animation":[91,91],"build":[121,132],"controller":[90,90],"dispose":[115,119],"initState":[93,113]},"supers":["State","SingleTickerProviderStateMixin"]},"_RallyTab":{"appearsIn":[["rally","h-widgets","Screen \u00b7 widget composition"]],"code":"class _RallyTab extends StatefulWidget {\n  _RallyTab({\n    required ThemeData theme,\n    IconData? iconData,\n    required String title,\n    int? tabIndex,\n    required TabController tabController,\n    required this.isVertical,\n  })  : titleText = Text(title, style: theme.textTheme.labelLarge),\n        isExpanded = tabController.index == tabIndex,\n        icon = Icon(iconData, semanticLabel: title);\n\n  final Text titleText;\n  final Icon icon;\n  final bool isExpanded;\n  final bool isVertical;\n\n  @override\n  _RallyTabState createState() => _RallyTabState();\n}","file":"lib/studies/rally/home.dart","kind":"class","line":262,"members":{"_RallyTab":[263,272],"createState":[279,280],"icon":[275,275],"isExpanded":[276,276],"isVertical":[277,277],"titleText":[274,274]},"shot":"shots/code/_RallyTab.jpg","supers":["StatefulWidget","_RallyTabState"]},"_RallyTabBar":{"appearsIn":[["rally","h-widgets","Screen \u00b7 widget composition"]],"code":"class _RallyTabBar extends StatelessWidget {\n  const _RallyTabBar({\n    required this.tabs,\n    this.tabController,\n  });\n\n  final List<Widget> tabs;\n  final TabController? tabController;\n\n  @override\n  Widget build(BuildContext context) {\n    return FocusTraversalOrder(\n      order: const NumericFocusOrder(0),\n      child: TabBar(\n        // Setting isScrollable to true prevents the tabs from being\n        // wrapped in [Expanded] widgets, which allows for more\n        // flexible sizes and size animations among tabs.\n        isScrollable: true,\n        labelPadding: EdgeInsets.zero,\n        tabs: tabs,\n        controller: tabController,\n        // This hides the tab indicator.\n        indicatorColor: Colors.transparent,\n      ),\n    );\n  }\n}","file":"lib/studies/rally/home.dart","kind":"class","line":234,"members":{"_RallyTabBar":[235,238],"build":[243,259],"tabController":[241,241],"tabs":[240,240]},"shot":"shots/code/_RallyTabBar.jpg","supers":["StatelessWidget"]},"_RallyTabState":{"code":"class _RallyTabState extends State<_RallyTab>\n    with SingleTickerProviderStateMixin {\n  late Animation<double> _titleSizeAnimation;\n  late Animation<double> _titleFadeAnimation;\n  late Animation<double> _iconFadeAnimation;\n  late AnimationController _controller;\n\n  @override\n  void initState() {\n    super.initState();\n    _controller = AnimationController(\n      duration: const Duration(milliseconds: 200),\n      vsync: this,\n    );\n    _titleSizeAnimation = _controller.view;\n    _titleFadeAnimation = _controller.drive(CurveTween(curve: Curves.easeOut));\n    _iconFadeAnimation = _controller.drive(Tween<double>(begin: 0.6, end: 1));\n    if (widget.isExpanded) {\n      _controller.value = 1;\n    }\n  }\n\n  @override\n  void didUpdateWidget(_RallyTab oldWidget) {\n    super.didUpdateWidget(oldWidget);\n    if (widget.isExpanded) {\n      _controller.forward();\n    } else {\n      _controller.reverse();\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    if (widget.isVertical) {\n      return Column(\n        children: [\n          const SizedBox(height: 18),\n          FadeTransition(\n            opacity: _iconFadeAnimation,\n            child: widget.icon,\n          ),\n          const SizedBox(height: 12),\n          FadeTransition(\n            opacity: _titleFadeAnimation,\n            child: SizeTransition(\n              axis: Axis.vertical,\n              axisAlignment: -1,\n              sizeFactor: _titleSizeAnimation,\n              child: Center(child: ExcludeSemantics(child: widget.titleText)),\n            ),\n          ),\n          const SizedBox(height: 18),\n        ],\n      );\n    }\n\n    // Calculate the width of each unexpanded tab by counting the number of\n    // units and dividing it into the screen width. Each unexpanded tab is 1\n    // unit, and there is always 1 expanded tab which is 1 unit + any extra\n    // space determined by the multiplier.\n    final width = MediaQuery.of(context).size.width;\n    const expandedTitleWidthMultiplier = 2;\n    final unitWidth = width / (tabCount + expandedTitleWidthMultiplier);\n\n    return ConstrainedBox(\n      constraints: const BoxConstraints(minHeight: 56),\n      child: Row(\n        children: [\n          FadeTransition(\n            opacity: _iconFadeAnimation,\n            child: SizedBox(\n              width: unitWidth,\n              child: widget.icon,\n            ),\n          ),\n          FadeTransition(\n            opacity: _titleFadeAnimation,\n            child: SizeTransition(\n              axis: Axis.horizontal,\n              axisAlignment: -1,\n              sizeFactor: _titleSizeAnimation,\n              child: SizedBox(\n                width: unitWidth * expandedTitleWidthMultiplier,\n                child: Center(\n                  child: ExcludeSemantics(child: widget.titleText),\n                ),\n              ),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  @override\n  void dispose() {\n    _controller.dispose();\n    super.dispose();\n  }\n}","file":"lib/studies/rally/home.dart","kind":"class","line":283,"members":{"_controller":[288,288],"_iconFadeAnimation":[287,287],"_titleFadeAnimation":[286,286],"_titleSizeAnimation":[285,285],"build":[315,376],"didUpdateWidget":[305,313],"dispose":[378,382],"initState":[290,303]},"supers":["State","SingleTickerProviderStateMixin"]},"_SettingsViewState":{"code":"class _SettingsViewState extends State<SettingsView> {\n  @override\n  Widget build(BuildContext context) {\n    return FocusTraversalGroup(\n      child: Container(\n        padding: EdgeInsets.only(top: isDisplayDesktop(context) ? 24 : 0),\n        child: ListView(\n          restorationId: 'settings_list_view',\n          shrinkWrap: true,\n          children: [\n            for (String title\n                in DummyDataService.getSettingsTitles(context)) ...[\n              _SettingsItem(title),\n              const Divider(\n                color: RallyColors.dividerColor,\n                height: 1,\n              )\n            ]\n          ],\n        ),\n      ),\n    );\n  }\n}","file":"lib/studies/rally/tabs/settings.dart","kind":"class","line":18,"members":{"build":[19,40]},"supers":["State"]}},"sourceUrl":"https://github.com/flutter/gallery/blob/d12640d4b08ee6e706fd8c64a83fba0620c9aa8d/"};
